const cfg = $input.first().json;
const nome = cfg.nome_cliente || 'Cliente Teste';

// ============================================================
// 4 CENÁRIOS DE PAYLOAD — escolha o que casa com seu template
// ============================================================

// A) Template SEM variáveis
const payloadSemParams = {
  from: cfg.from,
  to: cfg.to_test,
  type: 'template',
  template: {
    name: cfg.template_name,
    language: { code: cfg.language },
    components: []
  }
};

// B) Template com {{1}} APENAS no HEADER  ← reengajamento_clientes_servicos
const payloadHeaderOnly = {
  from: cfg.from,
  to: cfg.to_test,
  type: 'template',
  template: {
    name: cfg.template_name,
    language: { code: cfg.language },
    components: [
      {
        type: 'header',
        parameters: [{ type: 'text', text: nome }]
      }
    ]
  }
};

// C) Template com {{1}} APENAS no BODY
const payloadBodyOnly = {
  from: cfg.from,
  to: cfg.to_test,
  type: 'template',
  template: {
    name: cfg.template_name,
    language: { code: cfg.language },
    components: [
      {
        type: 'body',
        parameters: [{ type: 'text', text: nome }]
      }
    ]
  }
};

// D) Template com {{1}} em HEADER e BODY
const payloadHeaderAndBody = {
  from: cfg.from,
  to: cfg.to_test,
  type: 'template',
  template: {
    name: cfg.template_name,
    language: { code: cfg.language },
    components: [
      {
        type: 'header',
        parameters: [{ type: 'text', text: nome }]
      },
      {
        type: 'body',
        parameters: [{ type: 'text', text: nome }]
      }
    ]
  }
};

// ============================================================
// ESCOLHA AQUI o cenário do template que está testando:
// ============================================================
const payload = payloadHeaderOnly;  // ← padrão para reengajamento_clientes_servicos

return [{
  json: {
    body: JSON.stringify(payload),
    payload_preview: payload,
    to_display: cfg.to_test,
    template_used: cfg.template_name
  }
}];

const resp = $input.first().json;
const cfg = $('Configura Teste').first().json;
const payload = $('Monta Payload').first().json;

const status = resp.statusCode || resp.status || 'desconhecido';
const body = resp.body || resp;
const errorMsg = resp.error?.message || body?.message || body?.error?.message || null;

let diagnostico = '';
let sucesso = false;

if (status === 200 || status === 201) {
  sucesso = true;
  diagnostico = '✅ SUCESSO — Template enviado!\n\n' +
    'Verifique o WhatsApp ' + cfg.to_test + ' agora.\n' +
    'Se a mensagem chegou: o template está OK e pode ser usado no workflow principal.';
} else if (status === 400) {
  if (errorMsg && errorMsg.toLowerCase().includes('parameter')) {
    diagnostico = '❌ ERRO: Parameter mismatch\n\n' +
      'O template tem variável ({{1}}) que não foi preenchida — OU não tem variável mas você passou parâmetro.\n\n' +
      'SOLUÇÃO: Edite o nó "Monta Payload" e troque entre payloadSemParams ⇄ payloadComParams.';
  } else if (errorMsg && errorMsg.toLowerCase().includes('template')) {
    diagnostico = '❌ ERRO: Template não encontrado\n\n' +
      'Verifique:\n' +
      '1. O nome "' + cfg.template_name + '" está exatamente como aprovado no painel Meta\n' +
      '2. O template está com status APROVADO (não em revisão)\n' +
      '3. O idioma "' + cfg.language + '" corresponde ao do template';
  } else {
    diagnostico = '❌ ERRO 400 — Bad Request\n\nMensagem: ' + (errorMsg || 'sem detalhes');
  }
} else if (status === 401) {
  diagnostico = '❌ ERRO: 401 Unauthorized\n\n' +
    'A API Key da YCloud não está válida.\n' +
    'Verifique a credencial "YCloud Header Auth" no N8N.';
} else if (status === 404) {
  diagnostico = '❌ ERRO: 404 Not Found\n\nEndpoint não encontrado. Verifique a URL.';
} else if (status >= 500) {
  diagnostico = '⚠️ ERRO: Servidor YCloud (' + status + ')\n\nTente novamente em alguns minutos.';
} else {
  diagnostico = '⚠️ Status inesperado: ' + status + '\n\nResposta: ' + JSON.stringify(body, null, 2);
}

return [{
  json: {
    sucesso,
    status_code: status,
    template_testado: cfg.template_name,
    numero_destino: cfg.to_test,
    diagnostico,
    payload_enviado: payload.payload_preview,
    resposta_completa: body,
    erro_detalhado: errorMsg
  }
}];
